-- CreateSchema
CREATE SCHEMA IF NOT EXISTS "public";

-- CreateEnum
CREATE TYPE "Role" AS ENUM ('ADMIN', 'CASHIER');
CREATE TYPE "PaymentMethod" AS ENUM ('CASH', 'UPI', 'CARD', 'CREDIT', 'OTHER');
CREATE TYPE "InventoryMovementType" AS ENUM ('PURCHASE', 'SALE', 'RETURN', 'ADJUSTMENT');
CREATE TYPE "SaleStatus" AS ENUM ('COMPLETED', 'CANCELLED', 'RETURNED');
CREATE TYPE "ReturnStatus" AS ENUM ('COMPLETED', 'CANCELLED');

CREATE TABLE "Shop" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"address" TEXT,"phone" TEXT,"email" TEXT,"gstin" TEXT,"invoicePrefix" TEXT NOT NULL DEFAULT 'INV',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Shop_pkey" PRIMARY KEY ("id"));
CREATE TABLE "User" ("id" TEXT NOT NULL,"shopId" TEXT NOT NULL,"name" TEXT NOT NULL,"email" TEXT NOT NULL,"passwordHash" TEXT NOT NULL,"role" "Role" NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true,"counterId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Counter" ("id" TEXT NOT NULL,"shopId" TEXT NOT NULL,"name" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Counter_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Permission" ("id" TEXT NOT NULL,"code" TEXT NOT NULL,"description" TEXT,CONSTRAINT "Permission_pkey" PRIMARY KEY ("id"));
CREATE TABLE "UserPermission" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"permissionId" TEXT NOT NULL,"enabled" BOOLEAN NOT NULL DEFAULT true,CONSTRAINT "UserPermission_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Category" ("id" TEXT NOT NULL,"shopId" TEXT NOT NULL,"name" TEXT NOT NULL,CONSTRAINT "Category_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Product" ("id" TEXT NOT NULL,"shopId" TEXT NOT NULL,"sku" TEXT NOT NULL,"barcode" TEXT,"name" TEXT NOT NULL,"description" TEXT,"brand" TEXT,"unit" TEXT NOT NULL DEFAULT 'pcs',"purchasePrice" DECIMAL(65,30) NOT NULL,"sellingPrice" DECIMAL(65,30) NOT NULL,"mrp" DECIMAL(65,30),"taxRate" DECIMAL(65,30) NOT NULL DEFAULT 0,"stock" DECIMAL(65,30) NOT NULL DEFAULT 0,"minimumStock" DECIMAL(65,30) NOT NULL DEFAULT 0,"categoryId" TEXT,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Product_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Customer" ("id" TEXT NOT NULL,"shopId" TEXT NOT NULL,"name" TEXT NOT NULL,"phone" TEXT,"email" TEXT,"address" TEXT,"gstin" TEXT,"creditBalance" DECIMAL(65,30) NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Customer_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Supplier" ("id" TEXT NOT NULL,"shopId" TEXT NOT NULL,"name" TEXT NOT NULL,"phone" TEXT,"email" TEXT,"address" TEXT,"gstin" TEXT,"payableBalance" DECIMAL(65,30) NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Supplier_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Sale" ("id" TEXT NOT NULL,"shopId" TEXT NOT NULL,"invoiceNumber" TEXT NOT NULL,"cashierId" TEXT NOT NULL,"customerId" TEXT,"subtotal" DECIMAL(65,30) NOT NULL,"discount" DECIMAL(65,30) NOT NULL DEFAULT 0,"tax" DECIMAL(65,30) NOT NULL DEFAULT 0,"total" DECIMAL(65,30) NOT NULL,"idempotencyKey" TEXT,"status" "SaleStatus" NOT NULL DEFAULT 'COMPLETED',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Sale_pkey" PRIMARY KEY ("id"));
CREATE TABLE "SaleItem" ("id" TEXT NOT NULL,"saleId" TEXT NOT NULL,"productId" TEXT NOT NULL,"quantity" DECIMAL(65,30) NOT NULL,"unitPrice" DECIMAL(65,30) NOT NULL,"unitCost" DECIMAL(65,30) NOT NULL,"discount" DECIMAL(65,30) NOT NULL DEFAULT 0,"tax" DECIMAL(65,30) NOT NULL DEFAULT 0,"total" DECIMAL(65,30) NOT NULL,CONSTRAINT "SaleItem_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Payment" ("id" TEXT NOT NULL,"saleId" TEXT NOT NULL,"method" "PaymentMethod" NOT NULL,"amount" DECIMAL(65,30) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Payment_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Purchase" ("id" TEXT NOT NULL,"shopId" TEXT NOT NULL,"supplierId" TEXT,"invoiceNumber" TEXT NOT NULL,"total" DECIMAL(65,30) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Purchase_pkey" PRIMARY KEY ("id"));
CREATE TABLE "PurchaseItem" ("id" TEXT NOT NULL,"purchaseId" TEXT NOT NULL,"productId" TEXT NOT NULL,"quantity" DECIMAL(65,30) NOT NULL,"unitPrice" DECIMAL(65,30) NOT NULL,"total" DECIMAL(65,30) NOT NULL,CONSTRAINT "PurchaseItem_pkey" PRIMARY KEY ("id"));
CREATE TABLE "SaleReturn" ("id" TEXT NOT NULL,"shopId" TEXT NOT NULL,"saleId" TEXT NOT NULL,"userId" TEXT NOT NULL,"refundAmount" DECIMAL(65,30) NOT NULL,"reason" TEXT NOT NULL,"status" "ReturnStatus" NOT NULL DEFAULT 'COMPLETED',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "SaleReturn_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ReturnItem" ("id" TEXT NOT NULL,"returnId" TEXT NOT NULL,"saleItemId" TEXT NOT NULL,"productId" TEXT NOT NULL,"quantity" DECIMAL(65,30) NOT NULL,"amount" DECIMAL(65,30) NOT NULL,CONSTRAINT "ReturnItem_pkey" PRIMARY KEY ("id"));
CREATE TABLE "InventoryMovement" ("id" TEXT NOT NULL,"shopId" TEXT NOT NULL,"productId" TEXT NOT NULL,"type" "InventoryMovementType" NOT NULL,"quantity" DECIMAL(65,30) NOT NULL,"referenceId" TEXT,"reason" TEXT,"userId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "InventoryMovement_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ExpenseCategory" ("id" TEXT NOT NULL,"shopId" TEXT NOT NULL,"name" TEXT NOT NULL,CONSTRAINT "ExpenseCategory_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Expense" ("id" TEXT NOT NULL,"shopId" TEXT NOT NULL,"userId" TEXT,"categoryId" TEXT,"categoryName" TEXT,"amount" DECIMAL(65,30) NOT NULL,"description" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Expense_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AuditLog" ("id" TEXT NOT NULL,"shopId" TEXT NOT NULL,"userId" TEXT,"action" TEXT NOT NULL,"entity" TEXT NOT NULL,"entityId" TEXT,"metadata" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "AuditLog_pkey" PRIMARY KEY ("id"));
CREATE TABLE "InvoiceCounter" ("id" TEXT NOT NULL,"shopId" TEXT NOT NULL,"year" INTEGER NOT NULL,"value" INTEGER NOT NULL DEFAULT 0,CONSTRAINT "InvoiceCounter_pkey" PRIMARY KEY ("id"));
CREATE TABLE "IdempotencyKey" ("id" TEXT NOT NULL,"shopId" TEXT NOT NULL,"userId" TEXT NOT NULL,"operation" TEXT NOT NULL,"key" TEXT NOT NULL,"response" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "IdempotencyKey_pkey" PRIMARY KEY ("id"));

